/* here is code of animated border */
.form:focus-within:before {
  transform: scale(1);
}
/* styling of close button */
/* == you can click the close button to remove text == */
.reset {
  border: none;
  background: none;
  opacity: 0;
  visibility: hidden;
}
/* close button shown when typing */
input:not(:placeholder-shown) ~ .reset {
  opacity: 1;
  visibility: visible;
}
/* sizing svg icons */
.form svg {
  width: 17px;
  margin-top: 3px;
}

.slider-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

/* Äußerer Rahmen (Die helle Einkerbung) */
.slider-wrapper {
  position: relative;
  width: 200px; /* Auf 200px angepasst */
  height: 35px; /* Auf 35px angepasst */
  background: #d8d8d8;
  border-radius: 30px;
  padding: 6px;
  box-sizing: border-box;
  box-shadow:
    inset 2px 2px 5px rgba(0, 0, 0, 0.4),
    1px 1px 2px rgba(255, 255, 255, 0.8);
}

/* Basiseigenschaften für das native Range-Input */
.slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 100%;
  border-radius: 22px;
  outline: none;
  margin: 0;
  box-shadow: inset 0 3px 8px rgba(0, 0, 0, 0.7);
  cursor: pointer;
}

/* Individuelle Farbverläufe der Spuren */
.slider-gradient-1 {
  background: linear-gradient(to right, #ff2a00, #ff8c00, #ffea00);
}

.slider-gradient-2 {
  background: linear-gradient(to right, #008080, #00a8cc, #00d2ff);
}

.slider-gradient-3 {
  background: linear-gradient(to right, #0d0033, #5a004f, #aa0055);
}

.slider-gradient-4 {
  background: linear-gradient(to right, #00b300, #73e600, #ccff00);
}

/* --- METAL-KNAUF (THUMB) STYLING --- */

/* Für Chrome, Safari, Edge, Opera */
.slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 35px;
  height: 35px;
  border-radius: 50%;
  background: conic-gradient(
    from 180deg at 50% 50%,
    #7a8088 0deg,
    #c4c9cf 45deg,
    #eef1f5 90deg,
    #7a8088 135deg,
    #4a4e54 180deg,
    #c4c9cf 225deg,
    #eef1f5 270deg,
    #7a8088 315deg,
    #7a8088 360deg
  );
  border: 2px solid #5a5e63;
  box-shadow:
    0 4px 8px rgba(0, 0, 0, 0.5),
    inset 0 1px 2px rgba(255, 255, 255, 0.8),
    inset 0 -2px 4px rgba(0, 0, 0, 0.4);
  cursor: grab;
  transition: transform 0.1s ease;
}

.slider::-webkit-slider-thumb:active {
  cursor: grabbing;
  transform: scale(0.98);
}

/* Für Firefox */
.slider::-moz-range-thumb {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: conic-gradient(
    from 180deg at 50% 50%,
    #7a8088 0deg,
    #c4c9cf 45deg,
    #eef1f5 90deg,
    #7a8088 135deg,
    #4a4e54 180deg,
    #c4c9cf 225deg,
    #eef1f5 270deg,
    #7a8088 315deg,
    #7a8088 360deg
  );
  border: 2px solid #5a5e63;
  box-shadow:
    0 4px 8px rgba(0, 0, 0, 0.5),
    inset 0 1px 2px rgba(255, 255, 255, 0.8),
    inset 0 -2px 4px rgba(0, 0, 0, 0.4);
  cursor: grab;
}

